<script lang="ts">
	import OperatorGuard from '$lib/components/OperatorGuard.svelte'; import PlatformNav from '$lib/components/PlatformNav.svelte'; import StatusBadge from '$lib/components/StatusBadge.svelte'; import { formatInstant, sentence } from '$lib/format'; import { request } from '$lib/session.svelte';
	import type { EmailDeliveryResponse } from '$lib/generated/control-api';
	let deliveries=$state<EmailDeliveryResponse[]>([]),stateFilter=$state(''),error=$state(''),loading=$state(true);const filtered=$derived(deliveries.filter((item)=>!stateFilter||item.state===stateFilter));$effect(()=>{void load()});async function load(){try{deliveries=await request<EmailDeliveryResponse[]>('/v1/platform/email-deliveries');error=''}catch(cause){error=cause instanceof Error?cause.message:String(cause)}finally{loading=false}}
</script>
<svelte:head><title>Email delivery · MakersBrain</title></svelte:head>
<OperatorGuard><header class="page-header"><div><p class="eyebrow">Platform administration</p><h1>Email delivery</h1><p class="muted">Invitation and lifecycle delivery state. Message bodies and single-use links are never returned.</p></div><button class="secondary" onclick={load}>Refresh</button></header><PlatformNav />{#if error}<p class="error">{error}</p>{/if}<label class="card filter">State<select bind:value={stateFilter}><option value="">All states</option><option value="queued">Queued</option><option value="sending">Sending</option><option value="sent">Sent</option><option value="deferred">Deferred</option><option value="dead_letter">Needs attention</option></select></label><section class="section card table-wrap">{#if loading}<div class="empty">Loading deliveries…</div>{:else if filtered.length===0}<div class="empty">No deliveries in this state.</div>{:else}<table><thead><tr><th>Recipient</th><th>Template</th><th>State</th><th>Attempts</th><th>Created</th><th>Sent / next attempt</th></tr></thead><tbody>{#each filtered as item (item.id)}<tr><td>{item.recipient}</td><td>{sentence(item.template)}</td><td><StatusBadge state={item.state} /></td><td>{item.attempts}</td><td>{formatInstant(item.created_at)}</td><td>{formatInstant(item.sent_at??item.next_attempt_at)}</td></tr>{/each}</tbody></table>{/if}</section></OperatorGuard>
<style>.filter{max-width:18rem}</style>
